import React, { useCallback, useState } from 'react';

import styled from 'styled-components';

import type OpenFin from '@openfin/core';

import { Icon } from '@openfin/ui-library';

import { deleteWorkspace, switchWorkspace } from '@common/utils/global-context-menu';
import { showSuccess } from '@common/utils/indicators/showIndicator';
import { PositioningType } from '@common/utils/positioning';
import { dock3TestIds } from '@common/utils/test-ids';
import { raiseDockAnalytics } from '@common/utils/usage-register';

import { BaseCustomDropdownItem } from '@common/api/action';
import { useTranslation } from '@common/api/i18next';

import { BaseCustomDropdown } from '@common/components/CustomDropdown/BaseCustomDropdown';

import {
    deleteWorkspaceHandlerWithPayload,
    saveWorkspaceHandlerWithInjectables
} from '@client-platform/api/context-menu/utils';

import { openSaveWorkspaceModal } from '@dock3/components/utils';

import { wrapSync } from '@client-platform/api';
import { Dock3Config, GlobalContextMenuOptionType, SaveModalType, Workspace } from '@client-platform/shapes';
import { useDock3Context } from '@dock3/context/Dock3Context';

interface Props {
    platformIdentity?: OpenFin.Identity;
    dragging?: boolean;
}

const Container = styled.span`
    height: ${({ theme }) => theme.px.xxxlarge};
`;

type WorkspaceContextMenuAction =
    | { id: 'save-workspace-as' }
    | { id: 'rename-workspace' }
    | { id: 'new-window' }
    | { id: 'save-workspace' }
    | { id: 'restore-saved-workspace' }
    | { id: 'switch-workspace'; workspace: Workspace }
    | { id: 'delete-workspace'; workspace: Workspace };

const createDeleteSwitchWorkspaceMenuOption = (
    action: 'delete' | 'switch',
    savedWorkspaces: Workspace[],
    activeWorkspace?: Workspace
): BaseCustomDropdownItem => {
    const workspacesOptionsList =
        savedWorkspaces.length > 0
            ? savedWorkspaces.map(
                  (workspace): BaseCustomDropdownItem<WorkspaceContextMenuAction> => ({
                      checked: workspace.workspaceId === activeWorkspace?.workspaceId,
                      disabled: workspace.workspaceId === activeWorkspace?.workspaceId,
                      tooltip: workspace.title,
                      action: { id: `${action}-workspace`, workspace }
                  })
              )
            : [
                  {
                      disabled: true,
                      tooltip: 'No Workspaces Saved',
                      action: null
                  }
              ];
    return {
        tooltip: action === 'delete' ? deleteWorkspace().label : switchWorkspace().label,
        options: workspacesOptionsList,
        disabled: savedWorkspaces.length === 0
    };
};

const makeHandleOptions = (
    t: (str: string) => string,
    config: Dock3Config,
    platformIdentity?: OpenFin.Identity
): (() => Promise<BaseCustomDropdownItem[]>) => {
    return async () => {
        const platform = wrapSync(platformIdentity);
        const savedWorkspaces = await platform.Storage.getWorkspaces();
        const activeWorkspace = await platform.getCurrentWorkspace({ skipSnapshotUpdate: true });

        const lastSavedWorkspace = savedWorkspaces.find(
            (workspace) => workspace.workspaceId === activeWorkspace.workspaceId
        );

        const menuDefs: BaseCustomDropdownItem[] = [];

        if (config.uiConfig?.manageWorkspaces?.newWindow) {
            menuDefs.push({
                tooltip: t('contextMenu.newWindow'),
                action: { id: 'new-window' }
            });
            menuDefs.push({
                separator: true
            });
        }

        return menuDefs.concat([
            {
                tooltip: t('contextMenu.restore'),
                disabled: !savedWorkspaces.some(
                    (savedWorkspace) => savedWorkspace.workspaceId === activeWorkspace.workspaceId
                ),
                action: {
                    id: 'restore-saved-workspace'
                }
            },
            {
                tooltip: t('contextMenu.saveWorkspace'),
                disabled: !lastSavedWorkspace,
                action: {
                    id: 'save-workspace'
                }
            },
            {
                tooltip: t('contextMenu.saveWorkspaceAs'),
                action: {
                    id: 'save-workspace-as'
                }
            },
            {
                tooltip: t('contextMenu.renameWorkspace'),
                disabled: !lastSavedWorkspace,
                action: {
                    id: 'rename-workspace'
                }
            },
            createDeleteSwitchWorkspaceMenuOption('switch', savedWorkspaces, activeWorkspace),
            createDeleteSwitchWorkspaceMenuOption('delete', savedWorkspaces, activeWorkspace)
        ]);
    };
};

export const ManageWorkspaces: React.FC<Props> = ({ platformIdentity, dragging }) => {
    const [isLoading, setIsLoading] = useState(false);
    const { config } = useDock3Context();
    const { t } = useTranslation();

    const handleSelect = useCallback(
        async (action: WorkspaceContextMenuAction) => {
            try {
                setIsLoading(true);

                const platform = wrapSync(platformIdentity);
                switch (action.id) {
                    case 'new-window': {
                        switch (config.uiConfig?.manageWorkspaces?.newWindow?.behavior) {
                            case 'view':
                                await platform.createView(config.uiConfig.manageWorkspaces.newWindow.viewOptions);
                                break;
                            default: {
                                const exhaustiveCheck: never = config.uiConfig?.manageWorkspaces?.newWindow?.behavior;
                                console.error('new-window.view behavior is not supported:', exhaustiveCheck);
                            }
                        }
                        break;
                    }
                    case 'delete-workspace': {
                        await deleteWorkspaceHandlerWithPayload({
                            workspaceItemData: {
                                workspaceId: action.workspace.workspaceId,
                                type: GlobalContextMenuOptionType.DeleteWorkspace
                            },
                            positioning: PositioningType.RelativeToMonitor
                        });
                        break;
                    }
                    case 'switch-workspace': {
                        const workspace = action.workspace;
                        raiseDockAnalytics(platformIdentity, {
                            type: 'Workspace Selector',
                            action: 'Switch Workspace',
                            value: workspace.title
                        });
                        await platform.applyWorkspace(workspace, {
                            shouldCenterModalOnMonitor: true,
                            promptContainerWindowIdentity: fin.me.identity
                        });
                        break;
                    }
                    case 'restore-saved-workspace': {
                        const result = await platform.restoreLastSavedWorkspace();
                        if (result === 'success') {
                            await showSuccess({
                                message: t('dock.workspaceManagement.restoreSuccess'),
                                parentBrowserName: platformIdentity.name,
                                positioning: PositioningType.RelativeToMonitor
                            });
                        }
                        break;
                    }
                    case 'save-workspace-as': {
                        await openSaveWorkspaceModal({
                            menuType: SaveModalType.SAVE_WORKSPACE_AS
                        });
                        break;
                    }
                    case 'save-workspace': {
                        await saveWorkspaceHandlerWithInjectables({
                            showModal: async () => {
                                await openSaveWorkspaceModal({
                                    menuType: SaveModalType.SAVE_WORKSPACE
                                });
                            },
                            afterSuccessSave: async () => {
                                await showSuccess({
                                    message: t('successIndicator.workspaceSaved'),
                                    parentBrowserName: fin.me.identity.name,
                                    positioning: PositioningType.RelativeToMonitor
                                });
                            }
                        });
                        break;
                    }
                    case 'rename-workspace': {
                        await openSaveWorkspaceModal({
                            menuType: SaveModalType.RENAME_WORKSPACE
                        });
                        break;
                    }
                }
            } finally {
                setIsLoading(false);
            }
        },
        [config.uiConfig?.manageWorkspaces?.newWindow, platformIdentity]
    );

    return (
        <Container data-testid={dock3TestIds.manageWorkspacesContainer}>
            <BaseCustomDropdown
                data-testid={dock3TestIds.manageWorkspacesDropdown}
                tooltip="Manage Workspaces"
                options={makeHandleOptions(t, config, platformIdentity)}
                onSelect={handleSelect}
                disabled={isLoading}
                dragging={dragging}
                showArrow
                rounded
                size="xlarge"
            >
                <Icon icon="StackIcon" size="xlarge" />
            </BaseCustomDropdown>
        </Container>
    );
};

export default ManageWorkspaces;
