import React, { useCallback, useContext } from 'react';

import { FavoritesList } from '@dock3/components/FavoritesList';

import { getCurrentSync } from '@client-platform/api';
import { DockEntry } from '@client-platform/shapes';
import { useDefaultDockButtonsDynamic } from '@dock3/hooks/useDefaultDockButtonsDynamic';
import { DockContext } from '@enterprise/context/DockContext';

export const EnterpriseFavoritesList = () => {
    const { favorites, dockConfig } = useContext(DockContext);
    const [workspaceButtons] = useDefaultDockButtonsDynamic(dockConfig);

    const launchDockFavorite = useCallback((entry: DockEntry, e: MouseEvent) => {
        const { ctrlKey, metaKey, shiftKey } = e;
        // eslint-disable-next-line no-underscore-dangle
        getCurrentSync()._launchDockEntryInternal({
            entry,
            sourceEvent: {
                ctrlKey,
                metaKey,
                shiftKey
            }
        });
    }, []);

    const onRemoveFavorite = useCallback(async (entry: DockEntry) => {
        // eslint-disable-next-line no-underscore-dangle
        await getCurrentSync()._removeDockFavoriteInternal(entry);
    }, []);

    const onReorderFavorites = useCallback((reorderedFavorites: DockEntry[]) => {
        // eslint-disable-next-line no-underscore-dangle
        getCurrentSync()._setDockFavoritesInternal(reorderedFavorites);
    }, []);

    return (
        <FavoritesList
            favorites={favorites}
            launchDockFavorite={launchDockFavorite}
            defaultDockButtons={workspaceButtons}
            onRemoveFavorite={onRemoveFavorite}
            onReorderFavorites={onReorderFavorites}
        />
    );
};
