import React, { useState } from 'react';

import styled from 'styled-components';

import type OpenFin from '@openfin/core';

import { Icon } from '@openfin/ui-library';

import { dock3TestIds } from '@common/utils/test-ids';
import { raiseDockAnalytics } from '@common/utils/usage-register';

import { BaseCustomDropdownItem } from '@common/api/action';

import { BaseCustomDropdown } from '@common/components/CustomDropdown/BaseCustomDropdown';

import { wrapSync } from '@client-platform/api';
import { Collection } from '@client-platform/shapes';

interface Props {
    collectionMenu: Collection[];
    platformIdentity?: OpenFin.Identity;
    dragging?: boolean;
}

export const CollectionMenu: React.FC<Props> = ({ collectionMenu, platformIdentity, dragging }) => {
    const [isLoading, setIsLoading] = useState(false);
    const platform = wrapSync(platformIdentity);

    const handleSelect = async (collection: Collection) => {
        try {
            setIsLoading(true);
            raiseDockAnalytics(platformIdentity, {
                type: 'Collections Selector',
                action: 'Launch Collection',
                value: collection.title
            });
            // eslint-disable-next-line no-underscore-dangle
            await platform._launchCollectionInternal(collection);
        } finally {
            setIsLoading(false);
        }
    };

    const handleOptions = async (): Promise<BaseCustomDropdownItem[]> => {
        const options =
            collectionMenu.length > 0
                ? collectionMenu.map((collection) => ({
                      disabled: false,
                      tooltip: collection.title,
                      action: collection
                  }))
                : [
                      {
                          disabled: true,
                          tooltip: 'No Collections',
                          action: null as any
                      }
                  ];
        return [...options, { separator: true }];
    };

    return (
        <>
            <StyledDropdown
                data-testid={dock3TestIds.collectionMenuDropdown}
                tooltip="Collection Menu"
                options={handleOptions}
                onSelect={handleSelect}
                disabled={isLoading}
                dragging={dragging}
                showArrow
                rounded
                size="xlarge"
            >
                <Icon icon="CollectionIcon" size="xlarge" />
            </StyledDropdown>
        </>
    );
};

export default CollectionMenu;

const StyledDropdown = styled(BaseCustomDropdown)`
    height: ${({ theme }) => theme.px.xxxlarge};

    &:hover {
        background-color: var(--color-shared-icon-button-default-background-hover);
    }

    &:active {
        background-color: var(--color-shared-icon-button-default-background-selected);
    }

    &[aria-expanded='true'] {
        background-color: var(--color-shared-icon-button-default-background-pressed);
    }
`;
