import { useCallback, useContext, useEffect } from 'react';

import { withRouter } from 'next/router';

import { getThemedProviderIcon } from '@common/utils/getThemedProviderIcon';

// These constants are now in DockLayout.tsx
import { DockComponent } from '@dock3/components/DockComponent';
import { DockCompanionStyles, DockLayout, getDockComponentHeight } from '@dock3/components/DockLayout';
import { DockCompanionSeparator } from '@dock3/components/DockStyled';
import MoreMenu from '@dock3/components/MoreMenu';
import BrowserThemeProvider from '@enterprise/components/App/ThemeProvider/BrowserThemeProvider';
import { EnterpriseDefaultDockButtonsPanel } from '@enterprise/components/Dock/EnterpriseDefaultDockButtonsPanel';
import { EnterpriseDockContentMenu } from '@enterprise/components/Dock/EnterpriseDockContentMenu';
import { EnterpriseFavoritesList } from '@enterprise/components/Dock/EnterpriseFavoritesList';
import BookmarksPanel from '@enterprise/components/PanelContainer/BookmarksPanel/BookmarksPanel';

import { BrowserContext } from '@common/hooks/context';
import useSystemSchemeCheck from '@common/hooks/useSystemSchemeCheck';
import { WindowStateProvider } from '@common/hooks/useWindowFocusState';
import { useAlwaysOnTopSetting } from '@dock3/hooks/useAlwaysOnTopSetting';
import { useDockExpansion } from '@dock3/hooks/useDockExpansion';
import { BookmarksContextProvider } from '@enterprise/context/BookmarksContext';
import { DockContext, DockContextProvider } from '@enterprise/context/DockContext';
import useEnterpriseContextMenu from '@enterprise/hooks/useEnterpriseContextMenu';
import { useIsWindows } from '@enterprise/hooks/useIsWindows';

const DockCompanion = () => {
    useEnterpriseContextMenu();
    const isWindows = useIsWindows();
    const {
        dockChannel,
        dockConfig,
        contentMenuTargetId,
        clearContentMenuTargetId,
        customMenuOptions,
        customMenuLabel,
        moreMenuCustomOptionClicked,
        collectionMenu
    } = useContext(DockContext);

    const [alwaysOnTop, setAlwaysOnTop] = useAlwaysOnTopSetting();

    const {
        expandedComponent,
        isExpandedUp,
        toggleDockComponent: baseDockToggle
    } = useDockExpansion(clearContentMenuTargetId);

    // Extend toggleDockComponent to also clear the content menu target ID when closing
    const toggleDockComponent = useCallback(
        (dockComponent?: DockComponent) => {
            // Only clear the target ID if we're closing the content menu (not opening it)
            const isClosingContentMenu =
                expandedComponent === DockComponent.ContentMenu && dockComponent !== DockComponent.ContentMenu;

            if (isClosingContentMenu) {
                clearContentMenuTargetId();
            }

            baseDockToggle(dockComponent);
        },
        [baseDockToggle, clearContentMenuTargetId, expandedComponent]
    );

    const toggleBookmarks = useCallback(() => toggleDockComponent(DockComponent.Bookmarks), [toggleDockComponent]);

    const renderExpandedContent = useCallback(() => {
        return (
            <BookmarksContextProvider channel={dockChannel} toggleBookmarksOverride={toggleBookmarks}>
                {expandedComponent === DockComponent.ContentMenu && (
                    <EnterpriseDockContentMenu onClose={() => toggleDockComponent()} />
                )}
                {expandedComponent === DockComponent.Bookmarks && (
                    <BookmarksPanel onClose={() => toggleDockComponent()} />
                )}
            </BookmarksContextProvider>
        );
    }, [expandedComponent, toggleDockComponent, dockChannel, toggleBookmarks]);

    useEffect(() => {
        if (contentMenuTargetId && expandedComponent !== DockComponent.ContentMenu) {
            toggleDockComponent(DockComponent.ContentMenu);
        }
    }, [contentMenuTargetId, expandedComponent, toggleDockComponent]);

    // Get UI configuration
    const { hideDragHandle, providerIconContentMenu } = dockConfig?.uiConfig || {};
    const { isSchemeDark } = useSystemSchemeCheck();

    // The buttons panel to render in the left section
    const renderButtonsPanel = useCallback(
        () => (
            <EnterpriseDefaultDockButtonsPanel
                expandedComponent={expandedComponent}
                toggleDockComponent={toggleDockComponent}
                collectionMenu={collectionMenu}
            />
        ),
        [expandedComponent, toggleDockComponent]
    );

    // Center content is the favorites list
    const renderCenterContent = useCallback(() => <EnterpriseFavoritesList />, []);

    // Prepare the content for the right section of the dock
    const renderRightSectionContent = useCallback(
        () => (
            <>
                <DockCompanionSeparator />
                <MoreMenu
                    alwaysOnTop={alwaysOnTop}
                    setAlwaysOnTop={setAlwaysOnTop}
                    companionDockConfig={dockConfig}
                    customMenuOptions={customMenuOptions}
                    customMenuLabel={customMenuLabel}
                    onCustomMenuClick={moreMenuCustomOptionClicked}
                />
            </>
        ),
        [alwaysOnTop, setAlwaysOnTop, dockConfig, customMenuOptions, customMenuLabel, moreMenuCustomOptionClicked]
    );

    return (
        <DockLayout
            isWindows={isWindows}
            isExpandedUp={isExpandedUp}
            expandedComponent={expandedComponent}
            windowHeight={getDockComponentHeight(expandedComponent)}
            // Left section props
            hideDragHandle={hideDragHandle}
            providerIconContentMenu={providerIconContentMenu}
            iconURL={getThemedProviderIcon(dockConfig, isSchemeDark)}
            title={dockConfig?.title}
            isContentMenuOn={expandedComponent === DockComponent.ContentMenu}
            onProviderIconClick={() => toggleDockComponent(DockComponent.ContentMenu)}
            description={dockConfig?.title}
            renderButtonsPanel={renderButtonsPanel}
            renderCenterContent={renderCenterContent}
            renderRightSectionContent={renderRightSectionContent}
            renderExpandedContent={renderExpandedContent}
        />
    );
};

const Dock = () => {
    return (
        <BrowserContext>
            <BrowserThemeProvider>
                <WindowStateProvider>
                    <DockContextProvider>
                        <DockCompanionStyles />
                        <DockCompanion />
                    </DockContextProvider>
                </WindowStateProvider>
            </BrowserThemeProvider>
        </BrowserContext>
    );
};

export default withRouter(Dock);
